void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  {
    const int TI = 32;
    const int TJ = 32;
    const int TK = 32;

    #pragma omp parallel for schedule(guided) default(none) \
        shared(C, A, B, alpha, beta) private(i, j, k)
    for (i = 0; i < _PB_N; i++) {
      #pragma omp simd
      for (j = 0; j <= i; j++)
        C[i][j] *= beta;

      for (int jj = 0; jj <= i; jj += TJ) {
        int j_max = jj + TJ - 1;
        if (j_max > i) j_max = i;
        for (int kk = 0; kk < _PB_M; kk += TK) {
          int k_max = kk + TK - 1;
          if (k_max >= _PB_M) k_max = _PB_M - 1;
          for (j = jj; j <= j_max; j++) {
            DATA_TYPE cij = C[i][j];
            #pragma omp simd reduction(+:cij)
            for (k = kk; k <= k_max; k++) {
              cij += A[j][k] * alpha * B[i][k]
                   + B[j][k] * alpha * A[i][k];
            }
            C[i][j] = cij;
          }
        }
      }
    }
  }
#pragma endscop

}

